import React, { PropsWithChildren } from 'react';
import { isElement } from 'react-is';

import type { StylingProps } from '../../core/types/styling-props.js';

//#region Typings
/** Accepted properties for the Select EmptyState */
export type SelectV2EmptyStateProps = PropsWithChildren<unknown> & StylingProps;
//#endregion

/**
 * Typeguard function that will check if a React.Node is a SelectV2.EmptyState
 * @internal
 */
export function _isSelectV2EmptyState(
  child: React.ReactNode,
): child is React.ReactElement<SelectV2EmptyStateProps> {
  if (isElement(child) && child.type === SelectV2EmptyState) {
    return true;
  }
  return false;
}

/**
 * The `SelectV2.EmptyState` component allows you to specify any content, that should
 * be shown when no select options are available. The `SelectV2.EmptyState` component
 * is only valid within the `SelectV2.Content` element.
 * @example
 * ```tsx
 * <SelectV2.Content>
 *   <SelectV2.EmptyState>
 *     No items found.
 *   </SelectV2.EmptyState>
 * </SelectV2.Content>
 * ```
 */
export function SelectV2EmptyState(props: SelectV2EmptyStateProps) {
  return null;
}

SelectV2EmptyState.displayName = 'Select.EmptyState';
